function completeC011(){state.status='completed';state.stars=Math.max(1,4-Math.floor(state.hintsUsed/3));state.xpEarned=state.hintsUsed?300:330;state.completedAt=new Date().toISOString();if(!record||state.xpEarned>record.xpEarned||(state.xpEarned===record.xpEarned&&state.stars>record.stars))record=JSON.parse(JSON.stringify(state));state.scene=8;sound('case-complete');persist();render()}
