function handleC011Click(b){const task=c011Task();if(b.hasAttribute?.('data-mechanic-hint')){c011Hint();return}if(b.dataset.riddleAnswer!==undefined){if(state.solved[state.scene])return;state.attempts++;if(Number(b.dataset.riddleAnswer)===task.answer)completeC011Clue();else fail('Belum tepat. Fikirkan fungsi benda itu dan cuba lagi.');return}if(b.dataset.thirdAnswer!==undefined){if(state.solved[state.scene])return;state.attempts++;if(Number(b.dataset.thirdAnswer)===task.answer)completeC011Clue();else fail('Belum tepat. Bandingkan ketiga-tiga platform.');return}if(b.dataset.object){state.attempts++;if(state.scene===5&&b.dataset.object==='jalur tulisan'){if(!state.sceneProgress.busStation.includes('jalur tulisan'))state.sceneProgress.busStation.push('jalur tulisan');completeC011Clue()}else fail('Objek itu belum melengkapkan petunjuk ini. Cuba lagi.');return}if(b.dataset.thirdTheory!==undefined){state.attempts++;if(b.dataset.thirdTheory==='2'&&state.cluesFound===5&&state.solved[6])completeC011();else fail('Teori itu belum menerangkan semua petunjuk. Cuba lagi.');return}switch(b.dataset.action){case'start':home=false;file=false;render();break;case'home':home=true;file=false;persist();render();break;case'file':file=true;render();break;case'closefile':file=false;render();break;case'next':if(state.scene>=1&&state.scene<=6&&!state.solved[state.scene])return;state.scene++;feedback='';wrong=false;persist();render();break;case'hint':c011Hint();break;case'third-check':state.attempts++;if(state.cluesFound===5&&state.links.every((v,i)=>v===c011Evidence[i])){state.solved[6]=true;feedback='✓ Semua bukti disambungkan dengan tepat.';wrong=false;sound('board-complete');persist();render()}else fail('Sambungan belum lengkap. Semak hubungan setiap bukti.');break;case'replay':state=fresh11();record=cases.C011.record||record;home=false;file=false;feedback='';wrong=false;persist();render();break}}

